SELECT (SELECT group_concat(name || ':' || type || ':' || "notnull" || ':' || coalesce(dflt_value,'NULL') || ':' || pk, '|') FROM (SELECT * FROM pragma_table_info('t1') ORDER BY cid)) AS t1_columns, (SELECT group_concat(name || ':' || type || ':' || "notnull" || ':' || coalesce(dflt_value,'NULL') || ':' || pk, '|') FROM (SELECT * FROM pragma_table_info('t2') ORDER BY cid)) AS t2_columns, (SELECT group_concat("table" || ':' || "from" || ':' || coalesce("to",'') || ':' || on_update || ':' || on_delete || ':' || match, '|') FROM (SELECT * FROM pragma_foreign_key_list('t2') ORDER BY id, seq)) AS foreign_keys;